DECLARE second_org integer;v integer;sender_cfg jsonb;origin jsonb;request jsonb;check_result jsonb;sender_plan bigint;sender_job bigint;sender_campaign bigint;approved jsonb;sender_art jsonb;candidate jsonb;
BEGIN
 ASSERT pg_get_functiondef('sender_connection_gate(integer,jsonb)'::regprocedure)=current_setting('whatsapp_test.email_gate'),'email gate definition untouched';
 ASSERT pg_get_functiondef('outreach_email_step_begin(jsonb)'::regprocedure)=current_setting('whatsapp_test.email_begin'),'email begin definition untouched';
 ASSERT pg_get_functiondef('sender_connection_smtp_gate(integer,jsonb)'::regprocedure)=current_setting('whatsapp_test.smtp_gate'),'SMTP gate definition untouched';
 ASSERT pg_get_functiondef('outreach_smtp_begin(jsonb)'::regprocedure)=current_setting('whatsapp_test.smtp_begin'),'SMTP begin definition untouched';
 UPDATE org_sender_memberships SET active=true WHERE org_id=l.org_id;
 INSERT INTO organizations(org_name,status) VALUES('WhatsApp registry scratch only','active') RETURNING id INTO second_org;
 INSERT INTO org_sender_memberships(org_id,subject,role) VALUES(second_org,repeat('a',64),'owner');
 INSERT INTO credentials_entity(id,name,type,data) VALUES('wa-registry-credential','Scratch WhatsApp','whatsAppApi','fixture-only'),('wa-registry-other','Scratch other WhatsApp','whatsAppApi','fixture-only'),('wa-gmail-fixture','Scratch Gmail','gmailOAuth2','fixture-only'),('wa-smtp-fixture','Scratch SMTP','smtp','fixture-only'),('wa-imap-fixture','Scratch IMAP','imap','fixture-only');
 request:=jsonb_build_object('action','create','provider','whatsapp','connection_id','wa-registry','credential_ref','wa-registry-credential','sharing','private','limits','{"daily_messages":3,"rolling_24h_messages":1,"min_interval_seconds":300}'::jsonb,'whatsapp',jsonb_build_object('phone_number_id','555551111','waba_id','999991111','api_version','v99.0','credential_expires_at',now()+interval '7 days','identity_verified',false));
 ASSERT sender_connection_manage(l.org_id,repeat('a',64),request)->>'state'='pending_check','generic entry routes WhatsApp create';
 ASSERT (SELECT email IS NULL AND inbox_credential_ref IS NULL AND NOT send_capable AND NOT reply_capable AND channel_metadata->'identity_verified'='false'::jsonb FROM sender_connections WHERE org_id=l.org_id AND connection_id='wa-registry'),'WhatsApp registration does not fabricate email or readiness';
 ASSERT sender_whatsapp_manage(second_org,repeat('a',64),request||'{"connection_id":"other-org","credential_ref":"wa-registry-other"}'::jsonb)->>'error'='INVALID_OR_CONFLICTING_CONNECTION','same sender cannot belong to two orgs';
 ASSERT sender_whatsapp_manage(l.org_id,repeat('b',64),request||'{"sharing":"team","connection_id":"member-team"}'::jsonb)->>'error'='ADMIN_REQUIRED','team sender admin only';
 ASSERT sender_whatsapp_check_input(l.org_id,repeat('b',64),'wa-registry',1)->>'ready'='false','private sender check denied';
 ASSERT sender_whatsapp_check_input(l.org_id,repeat('a',64),'wa-registry',1)->>'ready'='true','owner can obtain private check task';
 e:=jsonb_build_object('signature_verified',true,'kind','inbound','provider_message_id','wamid.registered-before-campaign','phone_number_id','555551111','waba_id','999991111','recipient','+923008885555','text','STOP','occurred_at',now(),'org_id',second_org);
 ASSERT outreach_whatsapp_inbound_store(e)->>'saved'='false','pending registry cannot route unverified inbound';
 ASSERT sender_whatsapp_manage(l.org_id,repeat('a',64),request||'{"access_token":"MOCK"}'::jsonb)->>'error'='INVALID_WHATSAPP_CONNECTION','credential material rejected';
 check_result:=jsonb_build_object('org_id',l.org_id,'connection_id','wa-registry','credential_ref','wa-registry-credential','waba_id','999991111','phone_number_id','555551111','api_version','v99.0','state','identity_checked','verified_at',now(),'execution_authorized',false,'capabilities','{"account_sender_match":true}'::jsonb);
 ASSERT sender_whatsapp_checked(l.org_id,'wa-registry',1,check_result||'{"waba_id":"000001111"}'::jsonb)->>'state'='reconnect_required','wrong account check cannot verify';
 SELECT version INTO v FROM sender_connections WHERE org_id=l.org_id AND connection_id='wa-registry';
 ASSERT sender_connection_manage(l.org_id,repeat('a',64),jsonb_build_object('action','recheck','connection_id','wa-registry','expected_version',v))->>'state'='pending_check','generic recheck uses lifecycle lock';
 SELECT version INTO v FROM sender_connections WHERE org_id=l.org_id AND connection_id='wa-registry';
 ASSERT sender_whatsapp_checked(l.org_id,'wa-registry',v,check_result)->>'state'='identity_checked','matching trusted check verifies identity only';
 ASSERT sender_whatsapp_checked(l.org_id,'wa-registry',v,check_result)->>'error'='CHECK_STALE','stale completion rejected';
 SELECT version INTO v FROM sender_connections WHERE org_id=l.org_id AND connection_id='wa-registry';
 ASSERT sender_connection_checked(l.org_id,'wa-registry',v,'{"send":true,"read_replies":true}'::jsonb)->>'error'='WHATSAPP_CONNECTOR_REQUIRED','email checker cannot change WhatsApp state';
 ASSERT (SELECT NOT send_capable AND NOT reply_capable FROM sender_connections WHERE org_id=l.org_id AND connection_id='wa-registry'),'identity check is not send verification';
 r:=outreach_whatsapp_inbound_store(e);ASSERT r->>'saved'='true' AND r->>'org_id'=l.org_id::text,'verified registered sender routes inbound without any campaign';
 -- Existing email creation and field constraints still work.
 ASSERT sender_connection_manage(l.org_id,repeat('a',64),'{"action":"create","provider":"gmail","connection_id":"gmail-regression","credential_ref":"wa-gmail-fixture","email":"fixture@example.org","sharing":"private","limits":{"daily_limit":3,"mailbox_rolling_limit":3,"min_interval_seconds":300}}')->>'state'='pending_check','legacy Gmail create preserved';
 ASSERT sender_connection_manage(l.org_id,repeat('a',64),'{"action":"create","provider":"smtp","connection_id":"smtp-regression","credential_ref":"wa-smtp-fixture","inbox_credential_ref":"wa-imap-fixture","email":"smtp@example.org","sharing":"private","limits":{"daily_limit":3,"mailbox_rolling_limit":3,"min_interval_seconds":300}}')->>'state'='pending_check','legacy SMTP create preserved';
 BEGIN UPDATE sender_connections SET email=NULL WHERE org_id=l.org_id AND connection_id='gmail-regression';RAISE EXCEPTION 'EMAIL_NULL_ACCEPTED';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE sender_connections SET email='fake@example.org' WHERE org_id=l.org_id AND connection_id='wa-registry';RAISE EXCEPTION 'WA_FAKE_EMAIL_ACCEPTED';EXCEPTION WHEN check_violation THEN NULL;END;
 -- Create a fresh isolated campaign fixture for the managed sender.
 sender_cfg:=cfg;sender_cfg:=jsonb_set(sender_cfg,'{sequence}','[{"step":1,"channel":"whatsapp","delay_days":0}]'::jsonb);sender_cfg:=jsonb_set(sender_cfg,'{whatsapp_dispatch}',(sender_cfg->'whatsapp_dispatch')-'templates_by_step');
 INSERT INTO strategy_campaigns(org_id) VALUES(l.org_id) RETURNING id INTO sender_campaign;
 INSERT INTO strategy_campaign_versions(org_id,campaign_id,version,config) VALUES(l.org_id,sender_campaign,1,sender_cfg);origin:=sender_cfg;
 ASSERT sender_whatsapp_bind(l.org_id,repeat('b',64),'wa-registry',sender_campaign,1)->>'error'='sender_private','private binding denied';
 ASSERT sender_whatsapp_bind(l.org_id,repeat('a',64),'wa-registry',sender_campaign,1)->>'version'='2','bind creates fresh campaign version';
 SELECT config INTO sender_cfg FROM strategy_campaign_versions WHERE org_id=l.org_id AND campaign_id=sender_campaign AND version=2;
 ASSERT sender_cfg->'whatsapp_dispatch'->'enabled'='false'::jsonb AND sender_cfg->'whatsapp_dispatch'->'release'->'enabled'='false'::jsonb,'bind does not enable sending or release';
 ASSERT NOT(sender_cfg->'whatsapp_dispatch' ? 'template' OR sender_cfg->'whatsapp_dispatch' ? 'templates_by_step') AND sender_cfg->'whatsapp_dispatch'->'quote'->'verified'='false'::jsonb,'new binding invalidates prior account approval/pricing evidence';
 ASSERT (SELECT config=origin FROM strategy_campaign_versions WHERE org_id=l.org_id AND campaign_id=sender_campaign AND version=1),'old campaign content unchanged';
 ASSERT sender_whatsapp_gate(l.org_id,sender_cfg)->>'allowed'='true','registry binding identity matches';
 ASSERT sender_whatsapp_gate(l.org_id,sender_cfg-'whatsapp_sender_connection')->>'reason'='managed_whatsapp_binding_required','registry cannot be bypassed by deleting ref';
 ASSERT sender_whatsapp_gate(l.org_id,jsonb_set(sender_cfg,'{whatsapp_dispatch,limits,daily_messages}','4'))->>'reason'='sender_limit_mismatch','registry cap enforced';
 ASSERT sender_whatsapp_gate(second_org,sender_cfg)->>'allowed'='false','cross-org campaign denied';
 -- Fixture-only activation and exact plan approval, to test the REAL begin gate.
 UPDATE cleaned_leads SET phone='+923009997777' WHERE org_id=l.org_id AND id=l.id;
 UPDATE outreach_activities SET created_at=(now()-interval '2 days') AT TIME ZONE 'UTC',replied_at=NULL,bounced_at=NULL,dispatch_metadata=dispatch_metadata-'stop_reason'-'stop_events'-'followup_pause_reason' WHERE org_id=l.org_id AND lead_id=l.id;
 sender_cfg:=jsonb_set(sender_cfg,'{whatsapp_dispatch,enabled}','true');sender_cfg:=jsonb_set(sender_cfg,'{whatsapp_dispatch,campaign_state}','"running"');sender_cfg:=jsonb_set(sender_cfg,'{whatsapp_dispatch,release,enabled}','true');
 -- Explicit fresh mock provider evidence for this isolated account fixture.
 sender_cfg:=jsonb_set(sender_cfg,'{whatsapp_dispatch,template}',cfg->'whatsapp_dispatch'->'template');sender_cfg:=jsonb_set(sender_cfg,'{whatsapp_dispatch,quote}',cfg->'whatsapp_dispatch'->'quote');
 sender_cfg:=jsonb_set(sender_cfg,ARRAY['whatsapp_dispatch','consents',l.id::text,'phone'],'"+923009997777"');
 UPDATE strategy_campaign_versions SET config=sender_cfg WHERE org_id=l.org_id AND campaign_id=sender_campaign AND version=2;
 sender_art:=art||jsonb_build_object('recipient','+923009997777','connection_id','wa-registry','credential_ref','wa-registry-credential','phone_number_id','555551111','waba_id','999991111');
 approved:=jsonb_build_object('version','strategy_v2','state','template_completed','execution_authorized',false,'approval_required',true,'validation_errors','[]'::jsonb,'blocking_reasons','[]'::jsonb,'strategy','{"step1":{"channel":"whatsapp"}}'::jsonb,'artifacts',jsonb_build_object('whatsapp_dispatch',sender_art,'whatsapp_draft',sender_art->>'rendered'));
 INSERT INTO strategy_jobs(org_id,campaign_id,campaign_version,lead_id,request_id) VALUES(l.org_id,sender_campaign,2,l.id,'registry-scratch-'||sender_campaign) RETURNING id INTO sender_job;
 INSERT INTO strategy_plans(org_id,job_id,campaign_id,campaign_version,lead_id,body,fingerprint,content_hash,expires_at) VALUES(l.org_id,sender_job,sender_campaign,2,l.id,approved,strategy_context(l.org_id,sender_campaign,l.id)->>'fingerprint',md5(approved::text),now()+interval '1 day') RETURNING id INTO sender_plan;
 INSERT INTO strategy_approvals(org_id,plan_id,action,actor,content_hash) VALUES(l.org_id,sender_plan,'approve','scratch',md5(approved::text));
 candidate:=jsonb_build_object('org_id',l.org_id,'plan_id',sender_plan::text,'content_hash',md5(approved::text),'step',1);
 ASSERT outreach_whatsapp_gate(candidate)->>'allowed'='true','managed approved plan allowed: '||outreach_whatsapp_gate(candidate)::text;
 UPDATE org_sender_memberships SET active=false WHERE org_id=l.org_id AND subject=repeat('a',64);
 ASSERT outreach_whatsapp_begin(candidate)->>'reason'='sender_membership_revoked','membership revoked before begin blocks send';
 UPDATE org_sender_memberships SET active=true WHERE org_id=l.org_id AND subject=repeat('a',64);
 r:=outreach_whatsapp_begin(candidate);ASSERT r->>'authorized'='true','actual managed begin can claim: '||r::text;
 ASSERT sender_whatsapp_gate(l.org_id,sender_cfg)->>'reason'='whatsapp_sender_rolling_limit','rolling 24h cap shared across campaigns';
 ASSERT sender_connection_manage(l.org_id,repeat('a',64),jsonb_build_object('action','pause','connection_id','wa-registry','expected_version',v))->>'state'='disabled','generic pause routes through WhatsApp lock';
 ASSERT outreach_whatsapp_begin(candidate)->>'reason'='whatsapp_sender_not_ready','pause blocks atomic begin';
 ASSERT outreach_whatsapp_inbound_store(e||'{"provider_message_id":"wamid.registered-paused"}'::jsonb)->>'saved'='true','paused sender still receives STOP';
 ASSERT (SELECT body=approved AND content_hash=md5(approved::text) FROM strategy_plans WHERE id=sender_plan),'pause does not rewrite approved plan';
 SELECT version INTO v FROM sender_connections WHERE org_id=l.org_id AND connection_id='wa-registry';
 ASSERT sender_whatsapp_manage(l.org_id,repeat('a',64),jsonb_build_object('action','disconnect','connection_id','wa-registry','expected_version',v))->>'state'='disconnected','disconnect persisted';
 ASSERT outreach_whatsapp_gate(candidate)->>'allowed'='false','disconnect blocks future use';
 ASSERT outreach_whatsapp_inbound_store(e||'{"provider_message_id":"wamid.registered-disconnected"}'::jsonb)->>'saved'='true','disconnect does not discard later signed opt-outs';
 ASSERT sender_whatsapp_manage(l.org_id,repeat('a',64),jsonb_build_object('action','recheck','connection_id','wa-registry','expected_version',v))->>'error'='VERSION_CONFLICT','old lifecycle version rejected';
END;
